<script>
    const MODULES=[
      {title:"Module 1 - History of Healing Gardens",items:["Abbeys and monasteries","Early perfumer gardens","Inspirational healing gardens"]},
      {title:"Module 2 - Health Benefits of Healing Gardens",items:["Stress relief","Microbiota transfer","Ecosystem benefits; sensorial experience"]},
      {title:"Module 3 - The Fundamentals of Healthy Organic Soil",items:["Microbes; minerals; nitrogen and carbon","Planting a new garden bed","Invigorating an old garden bed"]},
      {title:"Module 4 - Plants for a Perfume Garden",items:["Fragrant flowers; fragrant herbs","Roses","Native plants"]},
      {title:"Module 5 - Landscaping Your Perfumer Garden",items:["Measuring up your area; design styles","Fundamentals of design; examples of healing garden designs","Making your sketch and final plan"]},
      {title:"Module 6 - Putting Everything Together",items:["Plant selection","Harvesting for therapeutic use","Maintenance of your healing garden"]},
    ];
    let openIdx=0;
    function renderAcc(){
      document.getElementById('accordion').innerHTML=MODULES.map((m,i)=>`
        <div class="border-b" style="border-color:rgba(11,65,49,.15);">
          <button onclick="openIdx=${openIdx===i?-1:i};renderAcc();" class="w-full flex items-center justify-between gap-4 text-white px-5 sm:px-6 py-5 text-left" style="background:var(--green-primary);">
            <span class="font-serif text-lg sm:text-xl lg:text-2xl">${m.title}</span>
            <svg class="shrink-0" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="transition:transform .3s;transform:rotate(${openIdx===i?180:0}deg)"><path d="M6 9l6 6 6-6"/></svg>
          </button>
          ${openIdx===i?`<div class="bg-white px-5 sm:px-6 lg:px-10 py-7"><ul class="space-y-3 text-[17px] sm:text-[18px] leading-relaxed" style="color:var(--text-dark);">${m.items.map(it=>`<li class="flex gap-3"><span style="color:var(--soft-sage);">&#9670;</span><span>${it}</span></li>`).join('')}</ul></div>`:''}
        </div>`).join('');
    }
    renderAcc();
    
  </script>

